import{u as n,o as i,c as r,j as e,k as s,F as l,a8 as c,e as d,p}from"./chunks/framework.fPNBP_58.js";const u=["markdown-url"],h={"data-allow-mismatch":"",style:{display:"none"}},v=JSON.parse('{"title":"Natural Capital Accountin with BCFI","description":"","frontmatter":{"layout":"page"},"headers":[],"params":{"narrative":"natural_capital_solution","file":"https://gtif-austria.github.io/public-narratives/natural_capital_solution.md","title":"Natural Capital Accountin with BCFI"},"relativePath":"narratives/natural_capital_solution.md","filePath":"narratives/[narrative].md"}'),m={name:"narratives/natural_capital_solution.md"},y=Object.assign(m,{setup(g){const a=p(!0);a.value=!1;const{params:o}=n();return(b,t)=>(i(),r("div",null,[e("client-only",null,[e("eox-storytelling",{"show-nav":"","markdown-url":s(o).file,"show-hero-scroll-indicator":"","show-map-loading-indicator":"",class:"full-width",style:{transform:"translateY(calc(var(--vp-nav-height) - 2px))","margin-top":"calc(var(--vp-nav-height) * -1 - 90px + 48px)","margin-bottom":"var(--vp-nav-height)","--eox-storytelling-hero-height":"auto"}},null,8,u)]),e("div",h,[a.value?(i(),r(l,{key:0},[t[0]||(t[0]=c(` --- cover-image: &quot;https://workspace-ui-public.gtif-austria.hub-otc.eox.at/api/public/share/public-4wazei3y-02/NCS/Thumbnail/ncs.jpg&quot; <h2 id="domain-carbon-accountingtags-land-cover-remote-sensing-national-inventory-reportprovider-ecosys-eox" tabindex="-1">domain: Carbon Accounting tags: land cover, remote sensing, National Inventory Report provider: ECOSYS,EOX <a class="header-anchor" href="#domain-carbon-accountingtags-land-cover-remote-sensing-national-inventory-reportprovider-ecosys-eox" aria-label="Permalink to &quot;domain: Carbon Accounting
tags: land cover, remote sensing, National Inventory Report
provider: ECOSYS,EOX&quot;">​</a></h2><h1 id="natural-capital-accountin-with-bcfi" tabindex="-1">Natural Capital Accountin with BCFI <a class="header-anchor" href="#natural-capital-accountin-with-bcfi" aria-label="Permalink to &quot;Natural Capital Accountin with BCFI &lt;!--{ as=&quot;img&quot; data-fallback-src=&quot;https://workspace-ui-public.gtif-austria.hub-otc.eox.at/api/public/share/public-4wazei3y-02/NCS/Thumbnail/ncs.jpg&quot; mode=&quot;hero&quot; src=&quot;https://workspace-ui-public.gtif-austria.hub-otc.eox.at/api/public/share/public-4wazei3y-02/NCS/Thumbnail/ncs.jpg&quot; }--&gt;&quot;">​</a></h1><h3 id="by-ecosys-eox" tabindex="-1">by ECOSYS - EOX <a class="header-anchor" href="#by-ecosys-eox" aria-label="Permalink to &quot;by ECOSYS - EOX &lt;!--{ style=&quot;font-size:1rem;opacity:0.7;margin-top:1rem;&quot; }--&gt;&quot;">​</a></h3><h2 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h2><p><strong>Empowering &amp; Scaling Nature-Positive Agriculture</strong> The transition to sustainable land management requires robust tools to measure and finance ecological outcomes. The <a href="https://ncs.eox.at/" target="_blank" rel="noreferrer">ECOSYS Natural Capital Solutions platform</a>, powered by EOX, acts as a foundational digital Measurement, Reporting, and Verification (dMRV) hub. Designed for the Green Transition, it bridges the gap between Earth Observation (EO) data, ecological science, real-world farming systems, and financial markets. By translating complex environmental signals into transparent, verifiable metrics, the platform empowers stakeholders to develop, evaluate, and scale biodiversity and carbon farming activities effectively. Within this framework, the yearly Biodiversity &amp; Carbon Farming Index (BCFI) for arable land provides a publicly accessible, parcel-level data infrastructure that links official land registry data with dynamic ecological performance indicators. By summarising EU-compliance-based metrics into a single comparable indicator across millions of individual parcels, the BCFI makes ecological change measurable, comparable, and traceable over time, ensuring that progress is demonstrable and outcomes are verifiable.</p><h2 id="the-context-challenge" tabindex="-1">The Context &amp; Challenge <a class="header-anchor" href="#the-context-challenge" aria-label="Permalink to &quot;The Context &amp; Challenge&quot;">​</a></h2><p><strong>Bridging the Gap Between Ecology and Capital</strong> Across Europe, arable croplands hold vast potential to sequester soil organic carbon, strengthen resilience against extreme weather events, and sustain farmland biodiversity. At the same time, evolving frameworks such as the Nature Restoration Law (NRL), the Common Agricultural Policy (CAP), and the Corporate Sustainability Reporting Directive (CSRD) are placing growing pressure on financial markets and the agricultural sector to measure and disclose ecological outcomes. Yet both sectors have historically lacked a unified method to quantify nature-related risks and environmental performance at the field level.</p><p>Translating high-level biodiversity goals into tangible, compliance-ready assets remains a central bottleneck. Evaluating the ecological impact of annual farming practices, including crop diversification, winter soil cover, and field-margin stewardship, has traditionally relied on costly manual field surveys or coarse regional averages, leaving biodiversity monitoring without scalable, parcel-level evidence. Without a reliable framework to establish baselines, evaluate risk, and monitor long-term progress at scale, unlocking finance for farmers who actively protect soil health, water resources, and biodiversity remains difficult.</p><p>Through an automated processing pipeline that integrates satellite observations products, the BCFI overcomes these limitations, making environmental and biodiversity monitoring faster, more cost-effective, and scalable from individual farm sites to entire regions.</p><h2 id="the-methodology" tabindex="-1">The Methodology <a class="header-anchor" href="#the-methodology" aria-label="Permalink to &quot;The Methodology&quot;">​</a></h2><p><strong>Biodiversity &amp; Carbon Farming Index</strong> To make the ecological outcomes of sustainable land management measurable, ECOSYS employs a science-led methodology that operates consistently from the individual parcel level up to national portfolios.</p><p>Data Integration: The framework fuses satellite-based Earth Observation signals with official parcel boundaries and compliance datasets (LPIS, IACS, and AMS), Area Monitoring System (AMS) event markers, soil maps, land-cover layers, and farm activity records.</p><p>The BCFI Metric: At the core of the methodology is the Biodiversity &amp; Carbon Farming Index (BCFI). This index is calculated through an automated pipeline in EOxHUB, a cloud-native geo-AI workflow that rates every arable parcel on four impacts categories : climate, soil, biodiversity and climate For every parcel, specialized subindexes are normalised, weighted according to their respective ecological contributions, and summed into a single composite BCFI score.</p><h2 id="stakeholders-applications" tabindex="-1">Stakeholders &amp; Applications <a class="header-anchor" href="#stakeholders-applications" aria-label="Permalink to &quot;Stakeholders &amp; Applications&quot;">​</a></h2><p><strong>Scalable Solutions for the Green Transition</strong> Accessible within the explorer interface, the BCFI indicator enables users to inspect individual parcel ratings, compare yearly performance, and examine the underlying subindex drivers behind each score. When paired with True Value Accounting (see <a href="https://ncs.eox.at/" target="_blank" rel="noreferrer">ECOSYS Natural Capital Solutions platform</a>) to translate ecological scores into standardized ecosystem-service valuations, the index delivers auditable, decision-ready intelligence that directly supports targeted CAP eco-scheme allocation, Nature Restoration Law and corporate sustainability reporting, ecological baseline verification, and de-risked investment in nature-positive agriculture across key sectors:</p><ul><li><p>Project Developers &amp; NGOs: Rapid landscape screening and parcel analytics establish ecological baselines, enabling the design of Nature-Based Solutions with verified impact metrics and investor-ready reporting. For instance, conservation organizations planning regional habitat corridors can pinpoint low-scoring arable parcels bordering existing hedgerows or waterways, target them for buffer strips or regenerative interventions, and document measurable multi-year biodiversity uplift.</p></li><li><p>Investors &amp; (Nature) Finance: Parcel-level analytics offer risk-adjusted valuations and compliance-ready evidence, allowing financial institutions to identify regenerative fields, de-risk investments, and confidently deploy capital. For example, agricultural lenders and nature-finance funds can evaluate farmland portfolios based on crop rotation diversity and spatial connectivity to surrounding habitats, using these subindexes to price long-term agronomic resilience, offer preferential financing for diversified cropping systems, or underwrite biodiversity-positive investments.</p></li><li><p>Supply Chains: Supply chain managers can monitor risks and verify regenerative sourcing claims across agricultural networks. For example, a grain buyer or food processor sourcing crops across thousands of contract farms can track annual winter soil cover, crop diversification, and erosion protection at the parcel level to substantiate Scope 3 emissions reductions and CSRD sustainability disclosures without relying solely on manual farm audits.</p></li></ul><p>Find further information about <a href="https://ncs.eox.at/" target="_blank" rel="noreferrer">ECOSYS</a></p><p>Explore <a href="https://gtif-austria.info/explore?indicator=ncs&amp;x=13.7500&amp;y=47.2688&amp;z=7.3868&amp;datetime=2025-01-01&amp;template=light" target="_blank" rel="noreferrer">Biodiversity Carbon Farming Index data of Austria</a></p>`,19))],64)):d("",!0)])]))}});export{v as __pageData,y as default};
